(function(){"use strict";const t=document.querySelector(".timeline-line-progress"),s=document.querySelectorAll(".timeline-item"),n=document.querySelector(".timeline-container");function i(){if(!t||!n)return;const e=n.getBoundingClientRect(),o=Math.max(0,Math.min(100,(window.innerHeight/2-e.top)/e.height*100));t.style.height=o+"%",s.forEach(function(c){const r=c.querySelector(".timeline-dot");if(r){const l=r.getBoundingClientRect().top-e.top;c.classList.toggle("active",o/100*e.height>=l)}})}window.addEventListener("scroll",i,{passive:!0}),i()})();
